-- Blogs locale merge
-- Source: Translations Spreadsheet_v3.xlsx - blogs-locales.csv
-- Data-only UPDATE. No ALTER TABLE. No published-flag changes.
-- Run in the Supabase SQL editor. One file at a time.
-- Merges en/it/fr/de/es into existing JSONB locale objects.
-- Skipped: blank cells, "" placeholders, empty arrays, empty objects, and lone "." cells.
-- Warning: admin editors still save only en/it. Saving there will wipe fr/de/es.

BEGIN;

-- blog_posts the-hidden-cost-of-hand-injuries
UPDATE blog_posts
SET
  title_locales = COALESCE(title_locales, '{}'::jsonb) || jsonb_build_object(
    'en', '"The Hidden Cost of Hand Injuries — And How Gloves Prevent Them"'::jsonb,
    'it', '"Il costo nascosto degli infortuni alle mani — e come i guanti li prevengono"'::jsonb,
    'fr', '"Le coût caché des accidents de la main — et comment les gants les préviennent"'::jsonb,
    'de', '"Die versteckten Kosten von Handverletzungen — und wie Handschuhe sie verhindern"'::jsonb,
    'es', '"El coste oculto de las lesiones en las manos — y cómo los guantes las previenen"'::jsonb
  ),
  summary_locales = COALESCE(summary_locales, '{}'::jsonb) || jsonb_build_object(
    'en', '"Hand injuries are the most common workplace non-fatal accident in EU and the UK. The right gloves can prevent up to 60% of injuries and boost safety, whilst cutting injury-related costs by billions."'::jsonb,
    'it', '"Gli infortuni alle mani sono gli incidenti sul lavoro non letali più comuni in Europa. I corretti guanti possono prevenire fino al 60% degli infortuni, riducendo al contempo i costi legati agli incidenti di miliardi di euro."'::jsonb,
    'fr', '"Les accidents de la main sont les accidents du travail non mortels les plus fréquents en Europe. Des gants adaptés peuvent prévenir jusqu''à 60 % des accidents, tout en réduisant de plusieurs milliards d''euros les coûts liés aux accidents."'::jsonb,
    'de', '"Handverletzungen sind die häufigsten nicht tödlichen Arbeitsunfälle in Europa. Die richtigen Handschuhe können bis zu 60 % der Unfälle verhindern und gleichzeitig die unfallbedingten Kosten um Milliarden von Euro senken."'::jsonb,
    'es', '"Las lesiones en las manos son los accidentes laborales no mortales más comunes en Europa. Los guantes adecuados pueden prevenir hasta el 60 % de las lesiones, reduciendo al mismo tiempo los costes relacionados con los accidentes en miles de millones de euros."'::jsonb
  ),
  content_locales = COALESCE(content_locales, '{}'::jsonb) || jsonb_build_object(
    'en', '"Our hands are our most valuable tools, but they’re also the most exposed part of the body in many workplaces. From construction sites to food processing plants, workers rely on their hands for precision, strength, and control. Unfortunately, this makes them especially vulnerable to injury — and the numbers across Europe tell a worrying story.  \n\n## The Scale of Hand Injuries in Europe and the UK  \n\nWorkplace accident data consistently shows that **hand and arm injuries are the most common type of workplace injury**. Across Europe, they represent more than **40% of all non-fatal accidents**, making them the single largest category of workplace injuries. Each year, there are an estimated **306,000 hand injuries**, **688,000 finger injuries**, and nearly **150,000 wrist injuries**.  \n\nThe economic impact is also significant. Hand and wrist injuries cost UK businesses around **£1.3 billion annually**, factoring in lost productivity, compensation, and healthcare costs.  \n\n## Common Types of Hand Injuries at Work  \n\nNot all hand injuries are the same, but most fall into a few common categories:  \n\n- **Cuts and lacerations** from glass, sheet metal, blades, or sharp tools.  \n- **Punctures and abrasions** caused by wires, nails, or rough surfaces.  \n- **Burns and chemical injuries**, which may cause permanent damage if the skin is exposed.  \n- **Sprains, fractures, and crush injuries**, often linked to machinery or heavy loads.  \n\nEven minor cuts can restrict dexterity and reduce productivity. More serious accidents can result in permanent loss of function or amputation — a life-changing outcome for the worker and their family.  \n\n## The Role of Safety Gloves in Preventing Hand Injuries  \n\nThe good news is that most of these accidents are preventable. Wearing the correct **PPE gloves for hand protection** can reduce injury risk by up to **60%**.  \n\nSafety gloves are designed to act as a barrier against mechanical, chemical, and thermal risks. However, not every glove is suitable for every task. The effectiveness of hand protection depends on choosing the right type:  \n\n- **Cut-resistant gloves** for handling sharp materials.  \n- **Chemical-resistant gloves** for solvents, oils, or hazardous substances.  \n- **Thermal gloves** for protection against extreme heat, sparks, or cold.  \n- **Impact-resistant gloves** for tasks involving vibration, shocks, or heavy tools.  \n\nWhen workers wear gloves designed for their task, they are better protected and can perform their jobs with greater confidence and safety.  \n\n## Why Hand Protection PPE is Not Always Used  \n\nIf protective gloves are so effective, why do hand injuries remain so common? The main reasons include:  \n\n- **Lack of awareness** of risks.  \n- **Incorrect glove selection**, leaving workers exposed.  \n- **Non-compliance**, when gloves feel uncomfortable or limit dexterity.  \n- **Cost-cutting**, with employers prioritising lower prices over proper protection.  \n\nAddressing these issues requires more than just supplying PPE — it requires a culture of safety where hand protection is a priority, not an afterthought.  \n\n## Best Practices for Employers and Workers  \n\nImproving workplace safety doesn’t have to be complicated. Here are key steps to reduce preventable hand injuries:  \n\n1. **Carry out risk assessments** to identify hand hazards in each role.  \n2. **Select the right safety gloves** for each hazard — cut, chemical, heat, or impact.  \n3. **Train workers** on proper PPE use and why it matters.  \n4. **Promote compliance** by offering comfortable, ergonomic gloves.  \n5. **Inspect and replace gloves** regularly to maintain protection.  \n\nWith these measures in place, businesses can dramatically lower the risk of workplace injuries, reduce downtime, and protect their most valuable asset — their people.  \n\n## Conclusion  \n\nHand injuries are the most frequent and costly workplace accidents in Europe and the UK, but they don’t have to be. With the correct use of **hand protection PPE gloves**, up to 60% of injuries can be avoided.  \n\nThe challenge is not availability but awareness and adoption. By selecting the right safety gloves and building a strong PPE culture, employers can protect their teams, reduce costs, and improve overall workplace safety.  \n\nHand protection is not just about compliance — it’s about protecting workers, preventing accidents, and creating safer, more productive workplaces."'::jsonb,
    'it', '"Le nostre mani sono i nostri strumenti più preziosi, ma anche la parte del corpo più esposta in molti ambienti di lavoro. Dai cantieri agli stabilimenti alimentari, i lavoratori fanno affidamento sulle mani per precisione, forza e controllo. Purtroppo, questo le rende particolarmente vulnerabili agli infortuni — e i dati in tutta Europa raccontano una storia preoccupante.\n\n## L’entità degli infortuni alle mani in Europa e nel Regno Unito\n\nI dati sugli incidenti sul lavoro mostrano costantemente che **gli infortuni a mani e braccia sono il tipo più comune di incidente sul lavoro**. In Europa rappresentano oltre il **40% di tutti gli incidenti non letali**, costituendo la categoria più numerosa di infortuni sul lavoro.  \n\nOgni anno si stimano:  \n- **306.000 infortuni alle mani**  \n- **688.000 infortuni alle dita**  \n- Quasi **150.000 infortuni al polso**  \n\nL’impatto economico è significativo. Gli infortuni a mani e polsi costano alle aziende del Regno Unito circa **1,3 miliardi di sterline all’anno**, considerando la perdita di produttività, indennizzi e spese sanitarie.\n\n## Tipologie comuni di infortuni alle mani sul lavoro\n\nNon tutti gli infortuni alle mani sono uguali, ma la maggior parte rientra in alcune categorie comuni:\n\n- **Tagli e lacerazioni** da vetro, lamiera, lame o utensili affilati  \n- **Punture e abrasioni** causate da fili, chiodi o superfici ruvide  \n- **Ustioni e lesioni chimiche**, che possono provocare danni permanenti se la pelle viene esposta  \n- **Distorsioni, fratture e schiacciamenti**, spesso legati a macchinari o carichi pesanti  \n\nAnche piccoli tagli possono ridurre la destrezza e la produttività. Incidenti più gravi possono comportare perdita permanente di funzionalità o amputazioni — un cambiamento radicale per il lavoratore e la sua famiglia.\n\n## Il ruolo dei guanti di protezione nella prevenzione degli infortuni alle mani\n\nLa buona notizia è che la maggior parte di questi incidenti è prevenibile. Indossare i **guanti DPI adeguati** può ridurre il rischio di infortuni fino al **60%**.\n\nI guanti di sicurezza sono progettati per agire come barriera contro rischi meccanici, chimici e termici. Tuttavia, non tutti i guanti sono adatti a ogni compito. L’efficacia della protezione dipende dalla scelta del tipo giusto:\n\n- **Guanti resistenti al taglio** per materiali affilati  \n- **Guanti resistenti a sostanze chimiche** per solventi, oli o sostanze pericolose  \n- **Guanti termici** per protezione da calore estremo, scintille o freddo  \n- **Guanti antiurto** per lavori con vibrazioni, urti o utensili pesanti  \n\nQuando i lavoratori indossano guanti progettati per il loro compito, sono meglio protetti e possono svolgere il lavoro con maggiore sicurezza e fiducia.\n\n## Perché i DPI per le mani non vengono sempre utilizzati\n\nSe i guanti di protezione sono così efficaci, perché gli infortuni alle mani restano così comuni? Le principali ragioni includono:\n\n- **Mancanza di consapevolezza** dei rischi  \n- **Scelta errata dei guanti**, che lascia i lavoratori esposti  \n- **Non conformità**, quando i guanti risultano scomodi o limitano la destrezza  \n- **Tagli ai costi**, con i datori di lavoro che privilegiano il prezzo rispetto alla protezione  \n\nAffrontare questi problemi richiede più della semplice fornitura di DPI — serve una cultura della sicurezza in cui la protezione delle mani sia una priorità, non un ripiego.\n\n## Buone pratiche per datori di lavoro e lavoratori\n\nMigliorare la sicurezza sul lavoro non deve essere complicato. Ecco i passaggi chiave per ridurre gli infortuni prevenibili alle mani:\n\n1. **Effettuare valutazioni dei rischi** per identificare i pericoli per le mani in ogni ruolo  \n2. **Selezionare i guanti di sicurezza appropriati** per ogni rischio — taglio, chimico, termico o impatto  \n3. **Formare i lavoratori** sull’uso corretto dei DPI e sull’importanza di indossarli  \n4. **Promuovere la conformità** offrendo guanti comodi ed ergonomici  \n5. **Ispezionare e sostituire i guanti** regolarmente per mantenere la protezione  \n\nCon queste misure, le aziende possono ridurre drasticamente il rischio di infortuni, diminuire i tempi di inattività e proteggere il loro bene più prezioso — le persone.\n\n## Conclusione\n\nGli infortuni alle mani sono gli incidenti sul lavoro più frequenti e costosi in Europa e nel Regno Unito, ma non devono esserlo. Con l’uso corretto dei **guanti DPI per la protezione delle mani**, fino al 60% degli infortuni può essere evitato.\n\nLa sfida non è la disponibilità, ma la consapevolezza e l’adozione. Selezionando i guanti di sicurezza giusti e promuovendo una solida cultura dei DPI, i datori di lavoro possono proteggere i loro team, ridurre i costi e migliorare la sicurezza complessiva sul lavoro.\n\nLa protezione delle mani non riguarda solo la conformità — significa proteggere i lavoratori, prevenire incidenti e creare ambienti di lavoro più sicuri e produttivi."'::jsonb,
    'fr', '"Nos mains sont nos outils les plus précieux, mais aussi la partie du corps la plus exposée dans de nombreux environnements de travail. Des chantiers aux usines agroalimentaires, les travailleurs comptent sur leurs mains pour la précision, la force et le contrôle. Malheureusement, cela les rend particulièrement vulnérables aux blessures — et les données à travers l''Europe racontent une histoire préoccupante.\n\n## L''ampleur des blessures aux mains en Europe et au Royaume-Uni\n\nLes données sur les accidents du travail montrent constamment que **les blessures aux mains et aux bras sont le type d''accident du travail le plus courant**. En Europe, elles représentent plus de **40 % de tous les accidents non mortels**, constituant la catégorie la plus nombreuse de blessures professionnelles.  \n\nChaque année, on estime :  \n- **306 000 blessures aux mains**  \n- **688 000 blessures aux doigts**  \n- Près de **150 000 blessures au poignet**  \n\nL''impact économique est significatif. Les blessures aux mains et aux poignets coûtent aux entreprises du Royaume-Uni environ **1,3 milliard de livres sterling par an**, en tenant compte de la perte de productivité, des indemnisations et des frais de santé.\n\n## Types courants de blessures aux mains au travail\n\nToutes les blessures aux mains ne se ressemblent pas, mais la plupart relèvent de quelques catégories communes :\n\n- **Coupures et lacérations** causées par du verre, de la tôle, des lames ou des outils tranchants  \n- **Piqûres et abrasions** causées par des fils, des clous ou des surfaces rugueuses  \n- **Brûlures et lésions chimiques**, pouvant provoquer des dommages permanents en cas d''exposition de la peau  \n- **Entorses, fractures et écrasements**, souvent liés aux machines ou aux charges lourdes  \n\nMême de petites coupures peuvent réduire la dextérité et la productivité. Des accidents plus graves peuvent entraîner une perte permanente de fonctionnalité ou des amputations — un bouleversement pour le travailleur et sa famille.\n\n## Le rôle des gants de protection dans la prévention des blessures aux mains\n\nLa bonne nouvelle est que la plupart de ces accidents sont évitables. Porter des **gants EPI adaptés** peut réduire le risque de blessure jusqu''à **60 %**.\n\nLes gants de sécurité sont conçus pour agir comme une barrière contre les risques mécaniques, chimiques et thermiques. Cependant, tous les gants ne conviennent pas à toutes les tâches. L''efficacité de la protection dépend du choix du bon type :\n\n- **Gants résistants à la coupure** pour les matériaux tranchants  \n- **Gants résistants aux produits chimiques** pour les solvants, huiles ou substances dangereuses  \n- **Gants thermiques** pour la protection contre la chaleur extrême, les étincelles ou le froid  \n- **Gants anti-chocs** pour les travaux impliquant des vibrations, des chocs ou des outils lourds  \n\nLorsque les travailleurs portent des gants conçus pour leur tâche, ils sont mieux protégés et peuvent effectuer leur travail avec plus de sécurité et de confiance.\n\n## Pourquoi les EPI pour les mains ne sont pas toujours utilisés\n\nSi les gants de protection sont si efficaces, pourquoi les blessures aux mains restent-elles si fréquentes ? Les principales raisons incluent :\n\n- **Manque de sensibilisation** aux risques  \n- **Mauvais choix de gants**, qui laisse les travailleurs exposés  \n- **Non-conformité**, lorsque les gants sont inconfortables ou limitent la dextérité  \n- **Réductions de coûts**, les employeurs privilégiant le prix plutôt que la protection  \n\nRésoudre ces problèmes nécessite plus qu''une simple fourniture d''EPI — il faut une culture de la sécurité dans laquelle la protection des mains est une priorité, et non un pis-aller.\n\n## Bonnes pratiques pour les employeurs et les travailleurs\n\nAméliorer la sécurité au travail ne doit pas être compliqué. Voici les étapes clés pour réduire les blessures évitables aux mains :\n\n1. **Réaliser des évaluations des risques** pour identifier les dangers pour les mains dans chaque rôle  \n2. **Sélectionner des gants de sécurité appropriés** pour chaque risque — coupure, chimique, thermique ou impact  \n3. **Former les travailleurs** à l''utilisation correcte des EPI et à l''importance de les porter  \n4. **Favoriser la conformité** en proposant des gants confortables et ergonomiques  \n5. **Inspecter et remplacer les gants** régulièrement pour maintenir la protection  \n\nAvec ces mesures, les entreprises peuvent réduire considérablement le risque de blessures, diminuer les temps d''arrêt et protéger leur bien le plus précieux — les personnes.\n\n## Conclusion\n\nLes blessures aux mains sont les accidents du travail les plus fréquents et les plus coûteux en Europe et au Royaume-Uni, mais elles ne devraient pas l''être. Avec l''utilisation correcte des **gants EPI pour la protection des mains**, jusqu''à 60 % des blessures peuvent être évitées.\n\nLe défi n''est pas la disponibilité, mais la sensibilisation et l''adoption. En sélectionnant les gants de sécurité adaptés et en promouvant une solide culture des EPI, les employeurs peuvent protéger leurs équipes, réduire les coûts et améliorer la sécurité globale au travail.\n\nLa protection des mains ne concerne pas seulement la conformité — elle signifie protéger les travailleurs, prévenir les accidents et créer des environnements de travail plus sûrs et plus productifs."'::jsonb,
    'de', '"Unsere Hände sind unsere wertvollsten Werkzeuge, aber auch der Körperteil, der in vielen Arbeitsumgebungen am stärksten exponiert ist. Von Baustellen bis zu Lebensmittelbetrieben verlassen sich die Arbeitnehmer für Präzision, Kraft und Kontrolle auf ihre Hände. Leider macht sie das besonders anfällig für Verletzungen — und die Daten aus ganz Europa erzählen eine besorgniserregende Geschichte.\n\n## Das Ausmaß der Handverletzungen in Europa und im Vereinigten Königreich\n\nDie Daten zu Arbeitsunfällen zeigen durchweg, dass **Verletzungen an Händen und Armen die häufigste Art von Arbeitsunfällen sind**. In Europa machen sie über **40 % aller nicht tödlichen Unfälle** aus und bilden damit die zahlenmäßig größte Kategorie von Arbeitsverletzungen.  \n\nJährlich werden geschätzt:  \n- **306.000 Handverletzungen**  \n- **688.000 Fingerverletzungen**  \n- Fast **150.000 Handgelenksverletzungen**  \n\nDie wirtschaftlichen Auswirkungen sind erheblich. Hand- und Handgelenksverletzungen kosten Unternehmen im Vereinigten Königreich schätzungsweise **1,3 Milliarden Pfund pro Jahr**, unter Berücksichtigung von Produktivitätsverlusten, Entschädigungen und Gesundheitskosten.\n\n## Häufige Arten von Handverletzungen am Arbeitsplatz\n\nNicht alle Handverletzungen sind gleich, aber die meisten lassen sich in einige gängige Kategorien einteilen:\n\n- **Schnitte und Risswunden** durch Glas, Blech, Klingen oder scharfe Werkzeuge  \n- **Stiche und Abschürfungen** durch Drähte, Nägel oder raue Oberflächen  \n- **Verbrennungen und chemische Verletzungen**, die bei Exposition der Haut dauerhafte Schäden verursachen können  \n- **Verstauchungen, Brüche und Quetschungen**, oft im Zusammenhang mit Maschinen oder schweren Lasten  \n\nSelbst kleine Schnitte können die Fingerfertigkeit und Produktivität beeinträchtigen. Schwerere Unfälle können zum dauerhaften Verlust der Funktionsfähigkeit oder zu Amputationen führen — eine einschneidende Veränderung für den Arbeitnehmer und seine Familie.\n\n## Die Rolle von Schutzhandschuhen bei der Vermeidung von Handverletzungen\n\nDie gute Nachricht ist, dass die meisten dieser Unfälle vermeidbar sind. Das Tragen geeigneter **PSA-Handschuhe** kann das Verletzungsrisiko um bis zu **60 %** senken.\n\nSicherheitshandschuhe sind so konzipiert, dass sie als Barriere gegen mechanische, chemische und thermische Gefahren wirken. Allerdings eignet sich nicht jeder Handschuh für jede Aufgabe. Die Wirksamkeit des Schutzes hängt von der Wahl des richtigen Typs ab:\n\n- **Schnittschutzhandschuhe** für scharfe Materialien  \n- **Chemikalienbeständige Handschuhe** für Lösungsmittel, Öle oder gefährliche Substanzen  \n- **Hitzeschutzhandschuhe** für Schutz vor extremer Hitze, Funken oder Kälte  \n- **Stoßschutzhandschuhe** für Arbeiten mit Vibrationen, Stößen oder schweren Werkzeugen  \n\nWenn Arbeitnehmer Handschuhe tragen, die für ihre Aufgabe konzipiert sind, sind sie besser geschützt und können ihre Arbeit mit mehr Sicherheit und Vertrauen ausführen.\n\n## Warum Hand-PSA nicht immer verwendet wird\n\nWenn Schutzhandschuhe so wirksam sind, warum bleiben Handverletzungen dann so häufig? Zu den Hauptgründen gehören:\n\n- **Mangelndes Bewusstsein** für die Risiken  \n- **Falsche Wahl der Handschuhe**, wodurch Arbeitnehmer exponiert bleiben  \n- **Nichteinhaltung**, wenn Handschuhe unbequem sind oder die Fingerfertigkeit einschränken  \n- **Kosteneinsparungen**, wobei Arbeitgeber dem Preis Vorrang vor dem Schutz geben  \n\nDie Lösung dieser Probleme erfordert mehr als nur die Bereitstellung von PSA — es braucht eine Sicherheitskultur, in der der Handschutz eine Priorität ist und nicht ein Notbehelf.\n\n## Bewährte Praktiken für Arbeitgeber und Arbeitnehmer\n\nDie Verbesserung der Arbeitssicherheit muss nicht kompliziert sein. Hier sind die wichtigsten Schritte zur Reduzierung vermeidbarer Handverletzungen:\n\n1. **Risikobewertungen durchführen**, um Gefahren für die Hände in jeder Rolle zu identifizieren  \n2. **Geeignete Sicherheitshandschuhe auswählen** für jedes Risiko — Schnitt, Chemikalien, Hitze oder Stoß  \n3. **Arbeitnehmer schulen** im korrekten Gebrauch der PSA und in der Bedeutung des Tragens  \n4. **Die Einhaltung fördern**, indem bequeme und ergonomische Handschuhe angeboten werden  \n5. **Handschuhe regelmäßig inspizieren und ersetzen**, um den Schutz aufrechtzuerhalten  \n\nMit diesen Maßnahmen können Unternehmen das Verletzungsrisiko drastisch senken, Ausfallzeiten verringern und ihr wertvollstes Gut schützen — die Menschen.\n\n## Fazit\n\nHandverletzungen sind die häufigsten und kostspieligsten Arbeitsunfälle in Europa und im Vereinigten Königreich, aber das muss nicht so sein. Durch den richtigen Einsatz von **PSA-Handschuhen zum Handschutz** können bis zu 60 % der Verletzungen vermieden werden.\n\nDie Herausforderung liegt nicht in der Verfügbarkeit, sondern im Bewusstsein und in der Umsetzung. Durch die Auswahl der richtigen Sicherheitshandschuhe und die Förderung einer soliden PSA-Kultur können Arbeitgeber ihre Teams schützen, Kosten senken und die allgemeine Sicherheit am Arbeitsplatz verbessern.\n\nHandschutz betrifft nicht nur die Compliance — er bedeutet, Arbeitnehmer zu schützen, Unfälle zu verhindern und sicherere, produktivere Arbeitsumgebungen zu schaffen."'::jsonb,
    'es', '"Nuestras manos son nuestras herramientas más valiosas, pero también la parte del cuerpo más expuesta en muchos entornos de trabajo. Desde las obras de construcción hasta las plantas alimentarias, los trabajadores confían en sus manos para la precisión, la fuerza y el control. Lamentablemente, esto las hace especialmente vulnerables a las lesiones — y los datos de toda Europa cuentan una historia preocupante.\n\n## La magnitud de las lesiones en las manos en Europa y el Reino Unido\n\nLos datos sobre accidentes laborales muestran sistemáticamente que **las lesiones en manos y brazos son el tipo de accidente laboral más común**. En Europa representan más del **40 % de todos los accidentes no mortales**, constituyendo la categoría más numerosa de lesiones laborales.  \n\nCada año se estiman:  \n- **306.000 lesiones en las manos**  \n- **688.000 lesiones en los dedos**  \n- Casi **150.000 lesiones en la muñeca**  \n\nEl impacto económico es significativo. Las lesiones en manos y muñecas cuestan a las empresas del Reino Unido aproximadamente **1300 millones de libras esterlinas al año**, considerando la pérdida de productividad, las indemnizaciones y los gastos sanitarios.\n\n## Tipos comunes de lesiones en las manos en el trabajo\n\nNo todas las lesiones en las manos son iguales, pero la mayoría se agrupan en algunas categorías comunes:\n\n- **Cortes y laceraciones** causados por vidrio, chapa metálica, cuchillas o herramientas afiladas  \n- **Pinchazos y abrasiones** causados por alambres, clavos o superficies rugosas  \n- **Quemaduras y lesiones químicas**, que pueden provocar daños permanentes si la piel queda expuesta  \n- **Esguinces, fracturas y aplastamientos**, a menudo relacionados con maquinaria o cargas pesadas  \n\nIncluso los cortes pequeños pueden reducir la destreza y la productividad. Los accidentes más graves pueden provocar la pérdida permanente de funcionalidad o amputaciones — un cambio drástico para el trabajador y su familia.\n\n## El papel de los guantes de protección en la prevención de lesiones en las manos\n\nLa buena noticia es que la mayoría de estos accidentes se pueden prevenir. Llevar **guantes EPI adecuados** puede reducir el riesgo de lesiones hasta en un **60 %**.\n\nLos guantes de seguridad están diseñados para actuar como barrera contra riesgos mecánicos, químicos y térmicos. Sin embargo, no todos los guantes son adecuados para cada tarea. La eficacia de la protección depende de elegir el tipo correcto:\n\n- **Guantes resistentes al corte** para materiales afilados  \n- **Guantes resistentes a sustancias químicas** para disolventes, aceites o sustancias peligrosas  \n- **Guantes térmicos** para protección contra calor extremo, chispas o frío  \n- **Guantes antiimpacto** para trabajos con vibraciones, golpes o herramientas pesadas  \n\nCuando los trabajadores llevan guantes diseñados para su tarea, están mejor protegidos y pueden realizar su trabajo con mayor seguridad y confianza.\n\n## Por qué los EPI para las manos no siempre se utilizan\n\nSi los guantes de protección son tan eficaces, ¿por qué las lesiones en las manos siguen siendo tan comunes? Las principales razones incluyen:\n\n- **Falta de concienciación** sobre los riesgos  \n- **Elección incorrecta de los guantes**, que deja a los trabajadores expuestos  \n- **Incumplimiento**, cuando los guantes resultan incómodos o limitan la destreza  \n- **Recortes de costes**, con empleadores que priorizan el precio sobre la protección  \n\nAbordar estos problemas requiere más que la simple provisión de EPI — se necesita una cultura de seguridad en la que la protección de las manos sea una prioridad, no un recurso secundario.\n\n## Buenas prácticas para empleadores y trabajadores\n\nMejorar la seguridad en el trabajo no tiene por qué ser complicado. Estos son los pasos clave para reducir las lesiones evitables en las manos:\n\n1. **Realizar evaluaciones de riesgos** para identificar los peligros para las manos en cada puesto  \n2. **Seleccionar los guantes de seguridad adecuados** para cada riesgo — corte, químico, térmico o impacto  \n3. **Formar a los trabajadores** en el uso correcto de los EPI y en la importancia de utilizarlos  \n4. **Fomentar el cumplimiento** ofreciendo guantes cómodos y ergonómicos  \n5. **Inspeccionar y sustituir los guantes** con regularidad para mantener la protección  \n\nCon estas medidas, las empresas pueden reducir drásticamente el riesgo de lesiones, disminuir el tiempo de inactividad y proteger su bien más valioso — las personas.\n\n## Conclusión\n\nLas lesiones en las manos son los accidentes laborales más frecuentes y costosos en Europa y el Reino Unido, pero no tienen por qué serlo. Con el uso correcto de los **guantes EPI para la protección de las manos**, hasta el 60 % de las lesiones pueden evitarse.\n\nEl reto no es la disponibilidad, sino la concienciación y la adopción. Al seleccionar los guantes de seguridad adecuados y fomentar una sólida cultura de EPI, los empleadores pueden proteger a sus equipos, reducir costes y mejorar la seguridad general en el trabajo.\n\nLa protección de las manos no se trata solo de cumplimiento — significa proteger a los trabajadores, prevenir accidentes y crear entornos de trabajo más seguros y productivos."'::jsonb
  ),
  tags_locales = COALESCE(tags_locales, '{}'::jsonb) || jsonb_build_object(
    'en', '["PPE", "injury costs", "safety gloves", "prevention"]'::jsonb,
    'it', '["DPI", "guanti di sicurezza", "prevenzione", "costo infortuni"]'::jsonb,
    'fr', '["EPI", "gants de sécurité", "prévention", "coût des accidents"]'::jsonb,
    'de', '["PSA", "Sicherheitshandschuhe", "Prävention", "Unfallkosten"]'::jsonb,
    'es', '["EPI", "guantes de seguridad", "prevención", "coste de los accidentes"]'::jsonb
  ),
  category_locales = COALESCE(category_locales, '{}'::jsonb) || jsonb_build_object(
    'en', '"Safety & Compliance"'::jsonb,
    'it', '"Sicurezza & Conformità"'::jsonb,
    'fr', '"Sécurité et conformité"'::jsonb,
    'de', '"Sicherheit & Konformität"'::jsonb,
